import numpy as np
def fill(g, mode):
    c=np.array(g); H,W=len(g),len(g[0])
    canvas=np.pad(c,((0,32-H),(0,32-W)),mode=mode)
    o=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]==8: o[i][j]=int(canvas[31-i][31-j])
    return o
# verify each demo against its stored cropped answer
def check(din, ans, r0, r1, c0_, c1_):
    for mode in ['edge','symmetric','reflect','wrap']:
        fo=fill(din,mode)
        ok=all(fo[r0+k][c0_+m]==ans[k][m] for k in range(r1-r0+1) for m in range(c1_-c0_+1))
        if ok: return mode
    return None
